/// Copied progress snapshot. Drain preserves reordered outputs; Flush discards unleased old outputs, resets parser/DPB and rejects stale-generation inputs. Close retains storage until all leases/worker resources retire.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct R4VideoState {
    /// Must be 1.
    pub r#version: u32,
    /// Must equal the complete fixed payload size.
    pub r#size: u32,
    /// Monotone generation starts at 1; successful Flush advances exactly once.
    pub r#stream_generation: u64,
    /// Current control ID or zero.
    pub r#pending_request: u64,
    /// Last completed control ID.
    pub r#completed_request: u64,
    /// Currently owned bytes including held old-generation outputs.
    pub r#memory_bytes: u64,
    /// Decoder phase.
    pub r#phase: u32,
    /// Accepted input packets not yet consumed.
    pub r#queued_packets: u32,
    /// Outputs waiting for receive.
    pub r#ready_frames: u32,
    /// Frames still held by consumers, including pending receipts.
    pub r#leased_frames: u32,
    /// Sticky terminal decoder error or zero.
    pub r#last_error: i32,
    /// Must be zero.
    pub r#reserved: u32,
}
const _: () = {
    assert!(core::mem::size_of::<R4VideoState>() == 64);
    assert!(core::mem::align_of::<R4VideoState>() == 8);
    assert!(core::mem::offset_of!(R4VideoState, r#version) == 0);
    assert!(core::mem::offset_of!(R4VideoState, r#size) == 4);
    assert!(core::mem::offset_of!(R4VideoState, r#stream_generation) == 8);
    assert!(core::mem::offset_of!(R4VideoState, r#pending_request) == 16);
    assert!(core::mem::offset_of!(R4VideoState, r#completed_request) == 24);
    assert!(core::mem::offset_of!(R4VideoState, r#memory_bytes) == 32);
    assert!(core::mem::offset_of!(R4VideoState, r#phase) == 40);
    assert!(core::mem::offset_of!(R4VideoState, r#queued_packets) == 44);
    assert!(core::mem::offset_of!(R4VideoState, r#ready_frames) == 48);
    assert!(core::mem::offset_of!(R4VideoState, r#leased_frames) == 52);
    assert!(core::mem::offset_of!(R4VideoState, r#last_error) == 56);
    assert!(core::mem::offset_of!(R4VideoState, r#reserved) == 60);
};

